 if(name==null||!(name.equals("java/io/File")||name.equals("java/nio/file/Files")||name.equals("dev/russiancompanion/data/local/LocalStore")||name.startsWith("dev/russiancompanion/data/local/LocalStore$")||name.startsWith("dev/russiancompanion/v2/")&&name.endsWith("Test")))return null;
