 private static boolean target(String n){return n.equals("open")||n.equals("openInMemory")||n.equals("openNamed")||n.contains("recoverInterruptedReplacementLocked")||n.contains("deleteReplacementJournal")||n.contains("sweepOrphanRecordingFiles")||n.equals("close")||n.contains("replaceGovernedLearner")||n.contains("replaceDocumentOnly")||n.contains("referencesResolve")||n.contains("copyRecordingFiles")||n.contains("stageIncomingRecordings")||n.contains("writeReplacementJournal")||n.contains("writeJournalAtomically")||n.contains("publishStagedRecordings")||n.contains("rollbackReplacementFiles")||n.contains("markReplacementJournalCommitted");}
